class Person:
    def __init__(self, name):
        self.name = name

    def greet(self):
        return "안녕하세요, " + self.name


class Student(Person):
    def __init__(self, name, sid):
        super().__init__(name)
        self.sid = sid

    def greet(self):
        return super().greet() + " (학번 " + str(self.sid) + ")"

setup:
def run_ops(obj, steps):
    out = []
    for step in steps:
        name, *args = step
        if name == "attr":
            out.append(getattr(obj, args[0]))
        elif name == "set":
            setattr(obj, args[0], args[1])
        else:
            r = getattr(obj, name)(*args)
            if r is not None:
                out.append(r)
    return out


def raises(fn):
    try:
        fn()
    except Exception as e:
        return type(e).__name__
    return None
